SELECT  ?var1Label ?var2 ?var3 ?var4
WHERE
  { OPTIONAL
      { wde:Q450007  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var5 )
        VALUES ( ?var5 ?var6 ) {
          ( "fr" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
