    UNION
      { ?var8  wdt:P21  wde:Q1097630 }
    UNION
      { ?var8  wdt:P21  wde:Q1052281 }
    UNION
      { ?var8  wdt:P21  wde:Q2449503 }
    OPTIONAL
      { ?var8  wdt:P569  ?var10 }
    BIND(year(?var10) AS ?var4)
    OPTIONAL
      { ?var8  wdt:P570  ?var11 }
    BIND(year(?var11) AS ?var5)
    ?var6  url:about  ?var8
    OPTIONAL
      { ?var8  rdfs:label  ?var1
        FILTER ( lang(?var1) = "fr" )
      }
    OPTIONAL
      { ?var9  rdfs:label  ?var2
        FILTER ( lang(?var2) = "fr" )
      }
